import Foundation

enum ToolCatalog {
    static func schema(_ fields: [String: String], required: [String]) -> JSONValue {
        .object(["type": .string("object"), "properties": .object(fields.mapValues { .object(["type": .string($0)]) }), "required": .array(required.map(JSONValue.string)), "additionalProperties": .bool(false)])
    }
    static let builtins: [ToolDefinition] = [
        .init(name: "list_files", description: "List files in a directory. Relative paths use the chat working directory.", parameters: schema(["path": "string"], required: ["path"])),
        .init(name: "read_file", description: "Read UTF-8 text with optional character offset and limit.", parameters: schema(["path": "string", "offset": "integer", "limit": "integer"], required: ["path"])),
        .init(name: "search_files", description: "Search file names and text under a folder. Bounded results.", parameters: schema(["path": "string", "query": "string"], required: ["path", "query"])),
        .init(name: "write_file", description: "Create or replace a UTF-8 file. Existing content is backed up. Returns an undo receipt.", parameters: schema(["path": "string", "content": "string"], required: ["path", "content"])),
        .init(name: "move_file", description: "Move/rename a file or folder; never overwrite destination.", parameters: schema(["source": "string", "destination": "string"], required: ["source", "destination"])),
        .init(name: "trash_file", description: "Move a file or folder into the macOS Trash, with undo receipt.", parameters: schema(["path": "string"], required: ["path"])),
        .init(name: "run_shell", description: "Run a zsh command for small local tasks. Never read Keychain, print credentials or use commands to bypass an approval. Prefer file tools for reversible operations. Timeout defaults120s. Optional environment_json is object envName:credential_id from request_secret. Never literal credentials.", parameters: schema(["command": "string", "timeout": "integer", "environment_json": "string"], required: ["command"])),
        .init(name: "ask_user", description: "Ask one clear question. Options separated by |; user can always type a custom answer. Do not ask for secrets here.", parameters: schema(["question": "string", "options": "string"], required: ["question"])),
        .init(name: "set_preference", description: "Change app theme (dark/light/system), lm_endpoint, comfy_endpoint, default_model, working_directory, font_size (11..24), spacing (12..48), question_level (0..4), image_prompt_language (auto/en/ru/zh/ja), web_search_enabled (true/false). Never edit application source to change preferences.", parameters: schema(["key": "string", "value": "string"], required: ["key", "value"])),
        .init(name: "connect_api", description: "Configure external REST API. Prompts a secure form for credential, stores only in Keychain. auth: bearer/header/basic/none/oauth. For oauth supply authorization_url/token_url/client_id/scopes; protected browser PKCE login. Never ask user to paste key in chat. Documentation directory created automatically. With basic auth, secure input is username:password.", parameters: schema(["name": "string", "base_url": "string", "auth": "string", "header_name": "string", "authorization_url": "string", "token_url": "string", "client_id": "string", "scopes": "string"], required: ["name", "base_url", "auth"])),
        .init(name: "list_connections", description: "List configured REST APIs, auth type, documentation paths. Never returns keys.", parameters: schema([:], required: [])),
        .init(name: "manage_connection", description: "Remove API connection and its Keychain credential, or securely replace credential. action: remove/replace_secret. Never supply actual secret in arguments.", parameters: schema(["connection_id": "string", "action": "string"], required: ["connection_id", "action"])),
        .init(name: "http_request", description: "Call configured API using Keychain credential injected by app. connection_id required; path is relative to base URL; method GET/POST/PUT/PATCH/DELETE; body is JSON string. No arbitrary headers, redirects or cross-origin URL. Results are redacted.", parameters: schema(["connection_id": "string", "path": "string", "method": "string", "body": "string"], required: ["connection_id", "path", "method"])),
        .init(name: "request_secret", description: "Collect password/key through protected form into Keychain. Returns only credential_id. To use API credentials prefer connect_api. Never requests secret in plain chat.", parameters: schema(["label": "string"], required: ["label"])),
        .init(name: "add_plugin", description: "Add MCP plugin. transport stdio or http. For stdio supply command and arguments_json JSON string array; for http supply url. First launch asks approval. Never put credentials in arguments or url.", parameters: schema(["name": "string", "transport": "string", "command": "string", "arguments_json": "string", "url": "string"], required: ["name", "transport"])),
        .init(name: "manage_plugin", description: "Enable/disable/remove plugin by plugin_id. action: enable/disable/remove.", parameters: schema(["plugin_id": "string", "action": "string"], required: ["plugin_id", "action"])),
        .init(name: "present_artifact", description: "Display response artifact in chat. kind html for interactive dashboard (inline JS/CSS only; no external network), mermaid for diagram, svg for vector diagram, markdown for document. content is complete UTF-8 source. title for filename.", parameters: schema(["kind": "string", "title": "string", "content": "string"], required: ["kind", "title", "content"])),
        .init(name: "import_image_workflow", description: "Import ComfyUI API workflow JSON as an image profile. workflow_json must contain exact string placeholders {{prompt}}, optional {{seed}} and {{checkpoint}} in input values; standard SaveImage output required. User can select profile beside /image in composer.", parameters: schema(["name": "string", "workflow_json": "string"], required: ["name", "workflow_json"])),
        .init(name: "show_file", description: "Show an existing local file/photo as an attachment in chat. Does not open external apps.", parameters: schema(["path": "string"], required: ["path"])),
        .init(name: "list_permissions", description: "List always-allowed exact actions as opaque IDs. These are host-side permissions; cannot grant via tools.", parameters: schema([:], required: [])),
        .init(name: "revoke_permissions", description: "Revoke all persistent approvals or a single scope. Cannot grant permissions.", parameters: schema(["scope": "string"], required: ["scope"]))
    ]
}
